#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Run from the repository root: bash scripts/setup-google-calendar.sh
# The keys go into apps/api/.env, which git ignores. Nothing is committed or sent anywhere else.
ENV_FILE="apps/api/.env"
TOTAL_STAGES=8

banner "Google Calendar for timedesk"

stage "Create a Google Cloud project"
say "Google needs a 'project' to hold timedesk's sign-in settings. It is free."
open_url "https://console.cloud.google.com/projectcreate"
step "Sign in with your Google account if asked."
step "Project name: timedesk. Leave the rest as it is, then press Create."
step "Wait a few seconds, then make sure 'timedesk' is selected in the project picker at the top of the page."
pause "Done? Press Enter."

stage "Turn on the Google Calendar API"
open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com"
step "Check that 'timedesk' is the selected project at the top."
step "Press Enable."
pause "Done? Press Enter."

stage "Sign-in screen: name and audience"
say "This is what you see when you connect: 'timedesk wants to access your calendar'."
open_url "https://console.cloud.google.com/auth/overview"
step "Press Get started (it may be called 'OAuth consent screen' in an older layout)."
step "App name: timedesk. User support email: your email. Next."
step "Audience: External. Next."
step "Contact information: your email. Next, tick the agreement, then Create."
note "If the page looks different: left menu, Google Auth platform (or APIs & Services, OAuth consent screen)."
pause "Done? Press Enter."

stage "Who may connect (test users)"
say "While the app is in Testing, only the people you list can connect. That is fine for a small team, and needs no Google review."
open_url "https://console.cloud.google.com/auth/audience"
step "Publishing status should say Testing. Leave it that way."
step "Under Test users press Add users and add your own Google email (and anyone else who will connect, up to 100)."
step "Save."
note "Good to know: in Testing, Google asks people to connect again after 7 days."
pause "Done? Press Enter."

stage "What timedesk may do (scopes)"
open_url "https://console.cloud.google.com/auth/scopes"
step "Press Add or remove scopes."
step "Tick these two (use the filter box to find them):"
say "    .../auth/calendar.events     (see, add, change and delete events)"
say "    .../auth/userinfo.email      (which Google account was connected)"
step "Press Update, then Save at the bottom."
pause "Done? Press Enter."

stage "Create the sign-in keys (OAuth client)"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Web application. Name: timedesk."
step "Authorized redirect URIs, press Add URI and paste exactly (no slash at the end):"
say "    http://localhost:3001/v1/integrations/google/callback"
ask PROD_API "Your live API address, for example https://api.example.com (Enter to skip for now):"
if [[ -n "${PROD_API:-}" ]]; then
  step "Press Add URI again and paste:"
  say "    ${PROD_API%/}/v1/integrations/google/callback"
else
  note "You can add the live address later on the same page: <your API address>/v1/integrations/google/callback"
fi
step "Press Create. Google shows the Client ID and the Client secret."
ask GOOGLE_CLIENT_ID "Paste the Client ID (ends with .apps.googleusercontent.com):"
ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret (hidden as you paste):"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
note "They are in $ENV_FILE now. That file is never committed to git."
pause "Press Enter to try it."

stage "Try it on your computer (your real calendar, a throwaway database)"
say "This runs timedesk with a temporary database, so your Neon data is not touched. Your Google Calendar is real."
say "Open two more terminals in this folder and run one command in each:"
say "    ${BOLD}pnpm --filter @timedesk/api dev:google${RESET}"
say "    ${BOLD}pnpm --filter @timedesk/web dev${RESET}"
pause "When both say they are running, press Enter."
open_url "http://localhost:5173/register"
step "Register with the email admin@local.test (any name and password): the test database makes it admin at once. Then sign in."
step "Go to Settings, Calendar, and press Connect Google Calendar."
step "Google warns 'Google hasn't verified this app': press Advanced, then Go to timedesk. Allow."
step "Back in timedesk it should say Connected, with your Google email."
step "Open the Calendar page: your real events should be there."
step "Optional: add a test event from timedesk, check it appears in Google Calendar, then delete it."
step "Optional: Wrap up the day (sidebar): a meeting today that no timer covered shows up as a suggestion."
if confirm "Did your events show up in timedesk?"; then
  say "${GREEN}Google Calendar works.${RESET} Stop the two terminals with Ctrl-C when you are done."
else
  warn "Things to check: the redirect URI is exactly http://localhost:3001/v1/integrations/google/callback,"
  warn "your Google email is a test user, and both scopes are added. Then press Connect again."
  SKIPPED+=("Google Calendar did not connect locally yet: see the checks above")
fi
pause "Press Enter for the last step."

stage "The live app (after you merge to main)"
say "Do this once the new version is merged and deployed:"
step "In Vercel, open the API project, Settings, Environment Variables, and add (Production):"
say "    GOOGLE_CLIENT_ID      = the same Client ID"
say "    GOOGLE_CLIENT_SECRET  = the same Client secret (copy it from $ENV_FILE)"
step "Make sure the live redirect address is on the Google client (stage 6), then Redeploy the API."
step "Apply the database migrations to Neon first: pnpm --filter @timedesk/db db:migrate"
step "In the live app: Settings, Calendar, Connect Google Calendar."
SKIPPED+=("Live app: add GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET to the API on Vercel, then redeploy (after merging)")
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
